begin;
create table if not exists public.ai_collaboration_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),scenario text not null check(scenario in('lead-created','deal-at-risk','new-customer','custom')),requested_by text not null check(requested_by in('sales-ai','crm-ai','marketing-ai','whatsapp-ai','voice-ai','operations-ai','finance-ai','executive-ai')),objective text not null check(char_length(objective)between 1 and 2000),related_customer_id uuid,status text not null default'active' check(status in('active','completed','error')),recommendation_only boolean not null default true check(recommendation_only),approval_required boolean not null default true check(approval_required),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.ai_collaboration_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),run_id uuid not null references public.ai_collaboration_runs(id)on delete cascade,employee_code text not null check(employee_code in('sales-ai','crm-ai','marketing-ai','whatsapp-ai','voice-ai','operations-ai','finance-ai','executive-ai')),summary text not null check(char_length(summary)between 1 and 2000),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.ai_collaboration_recommendations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),run_id uuid not null references public.ai_collaboration_runs(id)on delete cascade,employee_code text not null,request text not null,provider text not null,confidence numeric check(confidence between 0 and 1),approval_status text not null default'pending' check(approval_status in('pending','approved','rejected')),related_customer_id uuid,prompt_tokens integer not null default 0 check(prompt_tokens>=0),completion_tokens integer not null default 0 check(completion_tokens>=0),latency_ms integer check(latency_ms>=0),estimated_cost numeric(18,8)not null default 0 check(estimated_cost>=0),model text,recommendation_only boolean not null default true check(recommendation_only),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create index if not exists ai_collaboration_run_scope_idx on public.ai_collaboration_runs(organization_id,workspace_id,created_at desc);create index if not exists ai_collaboration_event_timeline_idx on public.ai_collaboration_events(organization_id,workspace_id,created_at desc);create index if not exists ai_collaboration_recommendation_graph_idx on public.ai_collaboration_recommendations(organization_id,workspace_id,run_id,created_at);
alter table public.ai_collaboration_runs enable row level security;alter table public.ai_collaboration_events enable row level security;alter table public.ai_collaboration_recommendations enable row level security;
create policy "collaboration_run_read" on public.ai_collaboration_runs for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "collaboration_run_insert" on public.ai_collaboration_runs for insert to authenticated with check(created_by=auth.uid()and recommendation_only and approval_required and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "collaboration_run_update" on public.ai_collaboration_runs for update to authenticated using(created_by=auth.uid()and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null)with check(created_by=auth.uid()and recommendation_only and approval_required);
create policy "collaboration_event_read" on public.ai_collaboration_events for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "collaboration_event_insert" on public.ai_collaboration_events for insert to authenticated with check(created_by=auth.uid()and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null and exists(select 1 from public.ai_collaboration_runs r where r.id=run_id and r.organization_id=organization_id and r.workspace_id=workspace_id));
create policy "collaboration_recommendation_read" on public.ai_collaboration_recommendations for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "collaboration_recommendation_insert" on public.ai_collaboration_recommendations for insert to authenticated with check(created_by=auth.uid()and recommendation_only and approval_status='pending'and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null and exists(select 1 from public.ai_collaboration_runs r where r.id=run_id and r.organization_id=organization_id and r.workspace_id=workspace_id));
create or replace function public.audit_ai_collaboration()returns trigger language plpgsql security definer set search_path=public as $$begin insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id,metadata)values(new.organization_id,new.workspace_id,'ai.collaboration.'||tg_op::text,'AI collaboration audit event',auth.uid(),'ai_collaboration',new.id,jsonb_build_object('table',tg_table_name,'recommendation_only',true,'approval_required',true));return new;end$$;
drop trigger if exists audit_ai_collaboration_run on public.ai_collaboration_runs;create trigger audit_ai_collaboration_run after insert or update on public.ai_collaboration_runs for each row execute function public.audit_ai_collaboration();drop trigger if exists audit_ai_collaboration_recommendation on public.ai_collaboration_recommendations;create trigger audit_ai_collaboration_recommendation after insert on public.ai_collaboration_recommendations for each row execute function public.audit_ai_collaboration();
commit;
